/** SQLDelight has no per-database connection-pool switch comparable to Room's, so S5c is Room-only. */
val SQ_SCENARIOS = listOf("S1", "S2", "S5", "S10")

fun openSqScenario(scenario: String, dir: String): List<DbHandle> = when (scenario) {
    "S1" -> listOf(
        sqHandle("MonoDb", "$dir/MonoDb.db", bench.sq.monodb.SqMonoDb.Schema) { d -> bench.sq.monodb.SqMonoDb(d).let { db -> db to listOf(db.t0Queries.ops(), db.t1Queries.ops(), db.t2Queries.ops(), db.t3Queries.ops(), db.t4Queries.ops(), db.t5Queries.ops(), db.t6Queries.ops(), db.t7Queries.ops(), db.t8Queries.ops(), db.t9Queries.ops()) } },
    )
    "S2" -> listOf(
        sqHandle("ContactsDb", "$dir/ContactsDb.db", bench.sq.contactsdb.SqContactsDb.Schema) { d -> bench.sq.contactsdb.SqContactsDb(d).let { db -> db to listOf(db.t0Queries.ops(), db.t1Queries.ops()) } },
        sqHandle("CalendarDb", "$dir/CalendarDb.db", bench.sq.calendardb.SqCalendarDb.Schema) { d -> bench.sq.calendardb.SqCalendarDb(d).let { db -> db to listOf(db.t2Queries.ops(), db.t3Queries.ops(), db.t4Queries.ops(), db.t5Queries.ops(), db.t6Queries.ops(), db.t7Queries.ops(), db.t8Queries.ops(), db.t9Queries.ops()) } },
    )
    "S5" -> listOf(
        sqHandle("FiveDb0", "$dir/FiveDb0.db", bench.sq.fivedb0.SqFiveDb0.Schema) { d -> bench.sq.fivedb0.SqFiveDb0(d).let { db -> db to listOf(db.t0Queries.ops(), db.t1Queries.ops()) } },
        sqHandle("FiveDb1", "$dir/FiveDb1.db", bench.sq.fivedb1.SqFiveDb1.Schema) { d -> bench.sq.fivedb1.SqFiveDb1(d).let { db -> db to listOf(db.t2Queries.ops(), db.t3Queries.ops()) } },
        sqHandle("FiveDb2", "$dir/FiveDb2.db", bench.sq.fivedb2.SqFiveDb2.Schema) { d -> bench.sq.fivedb2.SqFiveDb2(d).let { db -> db to listOf(db.t4Queries.ops(), db.t5Queries.ops()) } },
        sqHandle("FiveDb3", "$dir/FiveDb3.db", bench.sq.fivedb3.SqFiveDb3.Schema) { d -> bench.sq.fivedb3.SqFiveDb3(d).let { db -> db to listOf(db.t6Queries.ops(), db.t7Queries.ops()) } },
